    double? westDeg,
    double? EAST_DEG,
    double? eastDeg,
    etsAltitudeDatum? ALTITUDE_REFERENCE,
    etsAltitudeDatum? altitudeReference,
    double? ALTITUDE_MIN_M,
    double? altitudeMinM,
