    double? altitudeMaxM,
    double? TOLERANCE_H_M,
    double? toleranceHM,
    double? TOLERANCE_V_M,
    double? toleranceVM,
    double? ACHIEVED_MAX_ERROR_H_M,
    double? achievedMaxErrorHM,
    double? ACHIEVED_MAX_ERROR_V_M,
    double? achievedMaxErrorVM,
    etsCodec? CODEC,
    int? CODEC_VERSION,
    int? codecVersion,
    List<int>? PAYLOAD,
    ETSProvenanceObjectBuilder? SOURCE,
  })
      : _TRACK_ID = trackId ?? TRACK_ID,
        _SEGMENT_SEQ = segmentSeq ?? SEGMENT_SEQ,
        _TRACK_CLOSED = trackClosed ?? TRACK_CLOSED,
        _IDENTIFIERS = IDENTIFIERS,
        _ENVIRONMENT = ENVIRONMENT,
        _EPOCH = EPOCH,
        _END_EPOCH = endEpoch ?? END_EPOCH,
        _OBSERVATION_COUNT = observationCount ?? OBSERVATION_COUNT,
        _KNOT_COUNT = knotCount ?? KNOT_COUNT,
        _SOUTH_DEG = southDeg ?? SOUTH_DEG,
        _NORTH_DEG = northDeg ?? NORTH_DEG,
        _WEST_DEG = westDeg ?? WEST_DEG,
        _EAST_DEG = eastDeg ?? EAST_DEG,
        _ALTITUDE_REFERENCE = altitudeReference ?? ALTITUDE_REFERENCE,
        _ALTITUDE_MIN_M = altitudeMinM ?? ALTITUDE_MIN_M,
        _ALTITUDE_MAX_M = altitudeMaxM ?? ALTITUDE_MAX_M,
        _TOLERANCE_H_M = toleranceHM ?? TOLERANCE_H_M,
        _TOLERANCE_V_M = toleranceVM ?? TOLERANCE_V_M,
        _ACHIEVED_MAX_ERROR_H_M = achievedMaxErrorHM ?? ACHIEVED_MAX_ERROR_H_M,
        _ACHIEVED_MAX_ERROR_V_M = achievedMaxErrorVM ?? ACHIEVED_MAX_ERROR_V_M,
        _CODEC = CODEC,
