  int finish(fb.Builder fbBuilder) {
    final int? TRACK_IDOffset = _TRACK_ID == null ? null
        : fbBuilder.writeString(_TRACK_ID!);
    final int? IDENTIFIERSOffset = _IDENTIFIERS == null ? null
        : fbBuilder.writeList(_IDENTIFIERS!.map((b) => b.getOrCreateOffset(fbBuilder)).toList());
    final int? EPOCHOffset = _EPOCH == null ? null
        : fbBuilder.writeString(_EPOCH!);
    final int? END_EPOCHOffset = _END_EPOCH == null ? null
        : fbBuilder.writeString(_END_EPOCH!);
    final int? PAYLOADOffset = _PAYLOAD == null ? null
        : fbBuilder.writeListUint8(_PAYLOAD!);
    final int? SOURCEOffset = _SOURCE?.getOrCreateOffset(fbBuilder);
    fbBuilder.startTable(24);
    fbBuilder.addOffset(0, TRACK_IDOffset);
    fbBuilder.addUint32(1, _SEGMENT_SEQ);
    fbBuilder.addBool(2, _TRACK_CLOSED);
    fbBuilder.addOffset(3, IDENTIFIERSOffset);
    fbBuilder.addInt8(4, _ENVIRONMENT?.value);
    fbBuilder.addOffset(5, EPOCHOffset);
    fbBuilder.addOffset(6, END_EPOCHOffset);
    fbBuilder.addUint32(7, _OBSERVATION_COUNT);
    fbBuilder.addUint32(8, _KNOT_COUNT);
